// Builds kit/molde.js = vendored Alpine 3.17.5 (standard build) + src/sdk.cjs + src/components.js (no minifier, no CDN).
import { readFileSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';
const d = dirname(fileURLToPath(import.meta.url));
const r = (p) => readFileSync(join(d, p), 'utf8');
export function build() {
  return [
    '/* molde.js (kit 1, sdk 1). Alpine 3.17.5 (MIT, https://alpinejs.dev) + Molde SDK + components. Generated by kit/build.mjs. */',
    r('vendor/alpine-3.17.5.min.js').trim(), ';', r('src/sdk.cjs'), r('src/components.js'),
  ].join('\n');
}
if (process.argv[1] === fileURLToPath(import.meta.url)) { writeFileSync(join(d, 'molde.js'), build()); console.log('wrote kit/molde.js'); }
